/* Material original de práctica basado en las secciones del apunte de Diego Jauré. */
const chapters = ['Todos los capítulos','1 · Plano complejo','2 · Holomorfía','3 · Integración','4 · Residuos y consecuencias'];
const cards = [];
function card(ch,section,title,answer,example){cards.push({id:'c'+cards.length,ch,section,title,answer,example});}
card(1,'1.1','¿Qué son el conjugado y el módulo de z = x + iy?','z̄ = x − iy; |z| = √(x² + y²). Se cumple z·z̄ = |z|².','Para z = 3 − 4i: z̄ = 3 + 4i y |z| = 5.');
card(1,'1.2','¿Cómo se expresa un complejo no nulo en forma polar?','z = r eⁱᶿ, con r = |z| > 0. Sus argumentos son θ + 2kπ, k ∈ ℤ.','Multiplicar complejos multiplica módulos y suma argumentos.');
card(1,'1.2','¿Cuáles son las n raíces de un complejo r eⁱᶿ ≠ 0?','r^(1/n) exp(i(θ + 2kπ)/n), k = 0,…,n−1.','Las raíces están equiespaciadas en una circunferencia de radio r^(1/n).');
card(1,'1.3','¿Cuándo un conjunto es abierto?','Cada uno de sus puntos contiene un disco de radio positivo incluido en el conjunto.','El disco |z| < 1 es abierto; |z| ≤ 1 no lo es.');
card(1,'1.3','¿Qué caracteriza a un compacto de ℂ?','Es cerrado y acotado (Heine–Borel).','El anillo 1 ≤ |z| ≤ 2 es compacto.');
card(1,'1.3','¿Qué significa que un conjunto sea conexo?','No puede separarse en dos abiertos relativos no vacíos disjuntos. Un dominio es un abierto conexo.','ℂ ∖ {0} es conexo, aunque no simplemente conexo.');
card(1,'1.4','¿Qué diferencia hay entre convergencia puntual y uniforme?','Puntual: para cada z, fₙ(z) → f(z). Uniforme: sup sobre el dominio de |fₙ − f| → 0; el índice puede elegirse independientemente de z.','zⁿ → 0 en |z| < 1, uniformemente en |z| ≤ r < 1, pero no en todo el disco unidad.');
card(1,'1.4','¿Qué es la convergencia normal de una serie de funciones?','En un conjunto K, ∑ sup_K |fₙ| < ∞. Implica convergencia absoluta y uniforme en K.','Para ∑ zⁿ en |z| ≤ r < 1, la suma de las cotas es ∑ rⁿ = 1/(1−r).');
card(2,'2.1','¿Qué significa ser holomorfa en un abierto Ω?','Ser derivable en sentido complejo en cada punto de Ω. El cociente (f(z+h)−f(z))/h debe tener el mismo límite para toda dirección compleja de h → 0.','z² es holomorfa en ℂ; z̄ no es derivable complejamente en ningún punto.');
card(2,'2.2','¿Cuáles son las ecuaciones de Cauchy–Riemann?','Para f = u + iv: uₓ = vᵧ y uᵧ = −vₓ. Si u,v son C¹ en un abierto y cumplen estas igualdades allí, f es holomorfa.','No alcanza con verificar las igualdades en un punto sin hipótesis adicionales de regularidad.');
card(2,'2.2','¿Qué es una función biholomorfa?','Una biyección holomorfa cuya inversa también es holomorfa.','Si f′(a) ≠ 0, una función holomorfa admite una inversa holomorfa local cerca de a.');
card(2,'2.3','¿Cuándo una función holomorfa preserva ángulos localmente?','En un punto a donde f′(a) ≠ 0: su diferencial multiplica por f′(a), una rotación y una homotecia.','z² es conforme en a ≠ 0. En 0 duplica argumentos y no es conforme.');
card(2,'2.4','¿Qué es una rama del logaritmo?','Una función continua ℓ en un abierto de ℂ ∖ {0} tal que exp(ℓ(z)) = z. Es holomorfa y ℓ′(z) = 1/z.','Log z = ln|z| + i Arg z, con Arg ∈ (−π,π), en ℂ ∖ (−∞,0].');
card(2,'2.4','¿Por qué no hay un logaritmo holomorfo global en ℂ ∖ {0}?','Al dar una vuelta al origen, un argumento continuo aumenta 2π. Equivalentemente, ∮ dz/z = 2πi impide una primitiva global.','En un abierto simplemente conexo que evita 0 sí existe una rama.');
card(3,'3.1','¿Cómo se calcula una integral sobre un camino?','Para γ:[a,b]→ℂ de clase C¹ a trozos: ∫γ f(z) dz = ∫ₐᵇ f(γ(t)) γ′(t) dt.','Invertir el sentido del camino cambia el signo de la integral.');
card(3,'3.1','¿Qué dice la estimación ML?','|∫γ f(z) dz| ≤ longitud(γ) · supγ |f|.','En un círculo de radio R, la longitud es 2πR.');
card(3,'3.2','¿Qué dice la fórmula integral de Cauchy en un disco?','Si f es holomorfa en un entorno del disco cerrado y a está dentro de su borde γ orientado positivamente: ∮γ f(z)/(z−a) dz = 2πi f(a).','La hipótesis incluye el interior, no solamente el contorno.');
card(3,'3.3','¿Cuál es la fórmula integral para las derivadas?','∮γ f(z)/(z−a)^(n+1) dz = (2πi/n!) f⁽ⁿ⁾(a), con las hipótesis de Cauchy.','Para n = 1 se obtiene 2πi f′(a).');
card(3,'3.3','¿Qué relación hay entre holomorfía y analiticidad?','Una función es holomorfa si y solo si admite un desarrollo local en serie de potencias en cada punto. Es C∞.','Los coeficientes de Taylor en a son f⁽ⁿ⁾(a)/n!.');
card(3,'3.3','¿Cuáles son las estimaciones de Cauchy?','Si |f| ≤ M en |z−a| = R y f es holomorfa en un entorno del disco cerrado: |f⁽ⁿ⁾(a)| ≤ n! M/Rⁿ.','Para una función entera acotada se puede tomar R → ∞: f′ = 0.');
card(3,'3.4','¿Qué garantiza un límite holomorfo?','Si fₙ son holomorfas en Ω y convergen uniformemente en cada compacto de Ω, el límite es holomorfo y fₙ′ → f′ localmente uniformemente.','La convergencia puntual por sí sola no basta.');
card(4,'4.1','¿Qué es el residuo en una singularidad aislada a?','El coeficiente de (z−a)⁻¹ en el desarrollo de Laurent.','Si el polo es simple: Res(f,a) = lim(z→a) (z−a)f(z).');
card(4,'4.1','¿Cómo se calcula un residuo en un polo de orden m?','Res(f,a) = 1/(m−1)! · [d^(m−1)/dz^(m−1) ((z−a)^m f(z))] en z=a.','Para f(z)=eᶻ/z², el residuo en 0 es 1.');
card(4,'4.1','¿Qué es el índice de un lazo respecto de a?','Ind(γ,a) = (1/(2πi)) ∮γ dz/(z−a), si a no está en γ. Cuenta vueltas con signo.','Un círculo antihorario tiene índice 1 en su interior y 0 en el exterior.');
card(4,'4.1','¿Qué dice el teorema de los residuos?','Para f meromorfa en un abierto simplemente conexo y un lazo γ que evita sus polos: ∮γ f dz = 2πi ∑ Ind(γ,a) Res(f,a).','Un polo sobre el camino impide aplicar la fórmula de la integral ordinaria.');
card(4,'4.1','¿Cómo se clasifican las singularidades aisladas?','Removible: Laurent sin potencias negativas. Polo: un número finito no nulo de términos negativos. Esencial: infinitos términos negativos.','sin(z)/z es removible en 0; 1/z² tiene un polo doble; exp(1/z) es esencial.');
card(4,'4.3','¿Qué dice Liouville?','Toda función entera y acotada es constante.','Ser acotada solo en un disco no alcanza: f(z)=z está acotada en el disco unidad.');
card(4,'4.3','¿Qué dice el principio de identidad?','Dos funciones holomorfas en un dominio que coinciden en un conjunto con punto de acumulación dentro del dominio coinciden en todo él.','Una sucesión de ceros que solo acumula en la frontera no fuerza que f sea nula.');
card(4,'4.3','¿Qué dice Rouché?','Si f,g son holomorfas en un entorno de un dominio con borde simple cerrado y |g| < |f| en el borde, f y f+g tienen igual número de ceros dentro, contando multiplicidades.','La desigualdad se verifica sobre el borde.');
card(4,'4.4','¿Qué dice el principio del módulo máximo?','Si f es holomorfa en un dominio y |f| alcanza un máximo local en el interior, f es constante.','Si además es continua en la clausura de un dominio acotado, el máximo se alcanza en el borde.');
card(4,'4.4','¿Qué dice la propiedad de la media?','Para f holomorfa en un entorno del disco cerrado: f(a) = (1/2π) ∫₀²π f(a+reⁱᵗ) dt.','Se promedian los valores complejos, no sus módulos.');
card(4,'4.5','¿Cuándo existe una primitiva global?','Toda función holomorfa en un abierto simplemente conexo admite primitiva. En un dominio, tener primitiva equivale a que todas las integrales sobre lazos sean cero.','1/z tiene primitivas locales en ℂ ∖ {0}, pero ninguna global allí.');
card(4,'4.6','¿Qué es una función armónica real?','Una función u de clase C² que satisface Δu = uₓₓ + uᵧᵧ = 0.','Las partes real e imaginaria de una función holomorfa son armónicas.');
card(4,'4.6','¿Qué es una conjugada armónica?','Una función real v tal que u+iv es holomorfa. Existe globalmente para u armónica en un dominio simplemente conexo, y es única salvo una constante real.','Para u=x²−y², una conjugada es v=2xy.');

// Ampliación: definiciones, resultados y práctica breve de todas las secciones.
card(1,"1.1","¿Cómo se suman y multiplican dos complejos?","Se suman sus partes reales e imaginarias. (a+ib)(c+id) = (ac−bd)+i(ad+bc).","(1+2i)(3−i)=5+5i.");
card(1,"1.1","¿Cómo se calcula el inverso de un complejo no nulo?","1/z = z̄/|z|². El denominador es un real positivo.","1/(2+i)=(2−i)/5.");
card(1,"1.1","¿Cómo se recuperan Re z e Im z usando el conjugado?","Re z=(z+z̄)/2 e Im z=(z−z̄)/(2i).","La parte imaginaria es un número real.");
card(1,"1.1","¿Qué identidades cumple la conjugación con sumas y productos?","El conjugado de una suma es la suma de conjugados; el de un producto es el producto de conjugados.","También conmuta con cocientes cuyo denominador no es cero.");
card(1,"1.1","¿Cómo se comporta el módulo con productos y cocientes?","|zw|=|z||w| y |z/w|=|z|/|w| si w≠0.|El módulo de un inverso es 1/|w",".");
card(1,"1.1","¿Qué dicen las desigualdades triangular y triangular inversa?","|z+w|≤|z|+|w| y la diferencia absoluta entre |z| y |w| es ≤|z−w|.","En particular, el módulo es una función continua.");
card(1,"1.1","¿Cuándo hay igualdad en la desigualdad triangular para dos complejos no nulos?","Cuando ambos tienen el mismo argumento módulo 2π: uno es múltiplo real positivo del otro.","Para 1 e i la desigualdad es estricta.");
card(1,"1.2","¿Qué dice la fórmula de Euler?","eⁱᶿ = cos θ + i sin θ para θ real.","exp(iπ)=−1 y exp(iπ/2)=i.");
card(1,"1.2","¿Qué dice la fórmula de De Moivre?","(cos θ+i sin θ)ⁿ=cos(nθ)+i sin(nθ) para n entero.","Para exponentes negativos se usa el inverso; el módulo es 1.");
card(1,"1.2","¿Qué son las raíces n-ésimas de la unidad?","Las soluciones de wⁿ=1: exp(2πik/n), k=0,…,n−1.","Forman los vértices de un polígono regular.");
card(1,"1.2","¿Cuánto suman las raíces n-ésimas de la unidad si n≥2?","Cero, por la suma de una progresión geométrica.","Para n=2: 1+(−1)=0.");
card(1,"1.2","¿Qué diferencia hay entre argumento y argumento principal?","El argumento comprende todos los ángulos que representan z; el principal selecciona uno en un intervalo de longitud 2π.","Para la rama principal holomorfa usamos −π<Arg z<π y excluimos el corte.");
card(1,"1.2","¿Cómo se selecciona una raíz principal de un complejo no nulo?","Se elige un argumento principal θ y se toma |z|^(1/n) exp(iθ/n).","Una elección puntual no garantiza continuidad al cruzar el corte.");
card(1,"1.3","¿Qué distancia se usa en el plano complejo?","d(z,w)=|z−w|, la distancia euclídea de ℝ².","La distancia entre 1+i y 4+5i es 5.");
card(1,"1.3","¿Qué propiedades definen una norma?","Positividad y separación del cero, homogeneidad absoluta y desigualdad triangular.","El módulo es la norma euclídea de ℂ.");
card(1,"1.3","¿Qué es un disco abierto y qué es un disco perforado?","D(a,r) contiene los z con |z−a|<r; el perforado exige además z≠a.","Un entorno perforado permite estudiar singularidades aisladas.");
card(1,"1.3","¿Qué significa que una sucesión compleja converja a a?","Para todo ε>0 existe N tal que n≥N implica |zₙ−a|<ε.","Es equivalente a que converjan por separado las partes reales e imaginarias.");
card(1,"1.3","¿Qué es una sucesión de Cauchy en ℂ?","Para todo ε>0 existe N tal que m,n≥N implica |zₙ−zₘ|<ε.","ℂ es completo: toda sucesión de Cauchy converge en ℂ.");
card(1,"1.3","¿Qué es un punto interior de un conjunto A?","Un punto a para el que existe r>0 con D(a,r) incluido en A.","En el disco cerrado unidad, 0 es interior y 1 no.");
card(1,"1.3","¿Qué es la clausura de A?","El conjunto de puntos cuyos discos de cualquier radio positivo intersectan A.|La clausura de |z|<1 es |z","≤1.");
card(1,"1.3","¿Qué es la frontera de A?","Los puntos cuyos discos intersectan tanto A como su complemento.","La frontera del disco unidad es la circunferencia unidad.");
card(1,"1.3","¿Qué significa que A sea cerrado?","Que contiene todos sus puntos de clausura; equivalentemente, su complemento es abierto.","También contiene el límite de toda sucesión convergente de puntos de A.");
card(1,"1.3","¿Qué es un punto de acumulación de A?","Un punto a cuyo todo disco perforado intersecta A.","0 es de acumulación de {1/n: n≥1}, aunque no pertenezca al conjunto.");
card(1,"1.3","¿Qué es un punto aislado de A?","Un punto de A con algún disco que no contiene otros puntos de A.","Cada 1/n es aislado en {1/n: n≥1}.");
card(1,"1.3","¿Qué significa que un conjunto esté acotado?","Está contenido en algún disco de radio finito.","Ser cerrado no implica estar acotado.");
card(1,"1.3","¿Qué propiedad de sucesiones caracteriza la compacidad en ℂ?","Toda sucesión del conjunto tiene una subsucesión que converge a un punto del mismo conjunto.","Una sucesión de puntos del círculo unidad tiene una subsucesión convergente en él.");
card(1,"1.3","¿Qué garantiza Bolzano–Weierstrass en ℂ?","Toda sucesión acotada tiene una subsucesión convergente en ℂ.","El límite pertenece al conjunto si este es además cerrado.");
card(1,"1.3","¿Cómo se relacionan conexión y caminos en un abierto de ℂ?","Un abierto conexo es conexo por caminos; incluso se pueden unir sus puntos mediante caminos poligonales internos.","La hipótesis de abierto es relevante para esta equivalencia.");
card(1,"1.4","¿Cuál es la definición ε–δ de continuidad en a?","Para todo ε>0 existe δ>0 tal que z en el dominio y |z−a|<δ implican |f(z)−f(a)|<ε.","δ puede depender de a y de ε.");
card(1,"1.4","¿Cuál es el criterio secuencial de continuidad?","f es continua en a si para toda sucesión zₙ del dominio que converge a a, f(zₙ) converge a f(a).","Una sola sucesión que viole esto prueba discontinuidad.");
card(1,"1.4","¿Cómo se verifica continuidad mediante las partes real e imaginaria?","f=u+iv es continua si y solo si u y v son continuas como funciones de dos variables reales.","Los polinomios complejos son continuos en todo ℂ.");
card(1,"1.4","¿Qué es C(Ω)?","El espacio de funciones continuas de Ω en ℂ. Es un álgebra compleja con las operaciones puntuales.","La suma y el producto de funciones continuas son continuos.");
card(1,"1.4","¿Qué garantiza continuidad sobre un compacto?","La función es uniformemente continua y su módulo alcanza máximo y mínimo.","El compacto debe estar contenido en el dominio de continuidad.");
card(1,"1.4","¿Por qué el argumento principal salta en el corte?","Al acercarse al eje real negativo desde arriba y abajo, los argumentos tienden a π y −π.","No hay una elección continua del argumento en todo ℂ sin el origen.");
card(1,"1.4","¿Por qué una raíz principal puede ser continua en 0?","Su módulo es |z|^(1/n), que tiende a 0 independientemente del argumento elegido.","Esto no elimina el salto de la rama en los puntos no nulos del corte.");
card(1,"1.4","¿Qué es convergencia uniforme en compactos?","Convergencia uniforme en cada compacto K contenido en el dominio; también se llama convergencia localmente uniforme.","El índice N puede depender de K y de ε.");
card(1,"1.4","¿El límite uniforme de continuas es continuo?","Sí, sobre el mismo dominio de convergencia uniforme.","También basta convergencia uniforme local para obtener continuidad local.");
card(1,"1.4","¿Qué dice el criterio M de Weierstrass?","Si |fₙ(z)|≤Mₙ en E y la serie de Mₙ converge, la serie de fₙ converge absoluta y uniformemente en E.","Para zⁿ/n² en el disco cerrado unidad, usá Mₙ=1/n², n≥1.");
card(1,"1.4","¿Qué significa que una serie de funciones converja uniformemente?","Que sus sumas parciales convergen uniformemente a una función.","No debe confundirse con que los términos individuales tiendan uniformemente a cero.");
card(1,"1.4","¿Basta que los términos de una serie tiendan uniformemente a cero para que converja?","No. Es una condición necesaria, pero no suficiente.","Las funciones constantes fₙ(z)=1/n tienden uniformemente a cero y su serie diverge.");
card(1,"1.4","¿Cómo se define la exponencial compleja por una serie?","exp(z)=∑ zⁿ/n!, desde n=0. Converge absolutamente en ℂ y normalmente en cada compacto.|En |z","≤R se compara con ∑ Rⁿ/n!=eᴿ.");
card(2,"2.1","¿Qué son los operadores de Wirtinger?","∂/∂z=(∂/∂x−i∂/∂y)/2 y ∂/∂z̄=(∂/∂x+i∂/∂y)/2.","Se aplican a funciones diferenciables en las variables reales.");
card(2,"2.1","¿Cómo actúan los operadores de Wirtinger sobre z y z̄?","∂z/∂z=1, ∂z/∂z̄=0, ∂z̄/∂z=0 y ∂z̄/∂z̄=1.","Para estos cálculos se comportan como variables independientes.");
card(2,"2.1","¿Cómo se escribe el diferencial real usando Wirtinger?","df=f_z dz+f_z̄ dz̄.","El término en dz̄ mide la obstrucción a que el diferencial sea lineal complejo.");
card(2,"2.1","¿Cuál es la condición compleja de Cauchy para una función C¹?","f_z̄=0 en el abierto. Equivale a holomorfía y entonces f′=f_z.","Para f(z)=z̄, f_z̄=1 y la condición falla.");
card(2,"2.1","¿Qué operaciones preservan la holomorfía?","Combinaciones lineales, productos, composiciones y cocientes donde el denominador no se anula.","Las reglas de derivación son las usuales.");
card(2,"2.1","¿Qué es una función entera?","Una función holomorfa en todo ℂ.","Los polinomios y la exponencial son enteros; 1/z no lo es.");
card(2,"2.1","¿La derivabilidad compleja en un punto implica continuidad allí?","Sí: f(a+h)−f(a)=h(f′(a)+o(1)), que tiende a cero.","La continuidad por sí sola no implica derivabilidad compleja.");
card(2,"2.1","¿Qué regla cumple la derivada de una composición holomorfa?","(g∘f)′(a)=g′(f(a))f′(a), cuando la composición está definida.","La derivada de exp(z²) es 2z exp(z²).");
card(2,"2.2","¿Cómo se obtiene f′ a partir de las derivadas parciales?","Para una holomorfa f=u+iv, f′=uₓ+ivₓ=vᵧ−iuᵧ.","Se puede calcular el cociente incremental sobre la dirección real.");
card(2,"2.2","¿Cuál es el determinante jacobiano real de una función holomorfa?","Es |f′|². Si f′≠0 es positivo.","Una holomorfa con derivada no nula preserva orientación local.");
card(2,"2.2","¿Qué caracteriza al diferencial real de una holomorfa?","Es multiplicación por un número complejo; su matriz tiene filas (a,−b) y (b,a).","Aquí a+ib=f′ en el punto.");
card(2,"2.2","¿Qué derivada tiene la inversa biholomorfa?","Si w=f(z), entonces (f⁻¹)′(w)=1/f′(z).","Una biholomorfía tiene derivada no nula.");
card(2,"2.2","¿Una derivada no nula garantiza inyectividad global?","No. Garantiza una inversa holomorfa local.","exp(z) tiene derivada no nula, pero es periódica de período 2πi.");
card(2,"2.2","¿Cuál es la imagen de la exponencial compleja?","ℂ sin el origen: nunca se anula y todo complejo no nulo tiene alguna preimagen.","Las preimágenes de w difieren en múltiplos de 2πi.");
card(2,"2.2","¿Cuándo es constante una holomorfa con derivada nula?","Si su dominio es conexo y f′=0 en él, es constante.","En un abierto desconectado puede tomar una constante distinta en cada componente.");
card(2,"2.3","¿Qué escala y giro produce el diferencial de una holomorfa?","Escala por |f′(a)| y gira un argumento de f′(a), si f′(a)≠0.","Para f′(a)=2i: escala 2 y giro π/2.");
card(2,"2.3","¿Por qué hay que excluir tangentes nulas al hablar de ángulos entre curvas?","El ángulo se define mediante vectores tangentes no nulos.","Si una curva tiene velocidad cero, su derivada no determina una dirección tangente.");
card(2,"2.4","¿Cuál es el conjunto de todos los logaritmos de z≠0?","ln|z|+i(θ+2kπ), con θ un argumento de z y k entero.","Todos tienen la misma parte real.");
card(2,"2.4","¿Cómo difieren dos ramas del logaritmo en un dominio conexo?","En una constante 2πik, con k entero.","Su diferencia es continua y toma valores en un conjunto discreto.");
card(2,"2.4","¿Cómo se construye una rama del logaritmo con un corte de argumento θ?","Se elimina el rayo de ángulo θ y se elige el argumento en (θ−2π,θ).","La rama principal corresponde al corte del eje real no positivo.");
card(2,"2.4","¿Siempre vale Log(zw)=Log z+Log w en la rama principal?","No. Cuando los tres valores están definidos, pueden diferir en un múltiplo de 2πi.","Para z=w=exp(3πi/4), la suma es 3πi/2 y Log(zw)=−πi/2.");
card(2,"2.4","¿Cómo se define una potencia compleja usando una rama ℓ?","z^α=exp(αℓ(z)) en el dominio de ℓ.","Cambiar ℓ por ℓ+2πik multiplica el resultado por exp(2πikα).");
card(2,"2.4","¿Cuál es la derivada de una potencia definida por una rama?","(z^α)′=α exp((α−1)ℓ(z)), para α fijo.","Se deriva exp(αℓ(z)) usando ℓ′=1/z.");
card(2,"2.4","¿Por qué las potencias enteras no dependen de la rama del logaritmo?","Porque exp(2πikn)=1 para n entero.","Las raíces y potencias no enteras sí pueden depender de la rama.");
card(3,"3.1","¿Qué es un camino C¹ a trozos?","Una aplicación continua de un intervalo compacto, C¹ en las piezas de una partición finita.","Permite integrar sobre polígonos y concatenaciones de arcos suaves.");
card(3,"3.1","¿Qué es un lazo?","Un camino cuyo punto inicial coincide con el final.","No tiene por qué ser simple: puede cruzarse o dar varias vueltas.");
card(3,"3.1","¿Cómo se calcula la longitud de un camino C¹ a trozos?","Integrando |γ′(t)| respecto de t sobre su intervalo.","Para γ(t)=a+reⁱᵗ, 0≤t≤2π, vale 2πr.");
card(3,"3.1","¿Cómo se comporta la integral al concatenar caminos?","La integral sobre la concatenación es la suma de las integrales, si el final del primero es el inicio del segundo.","Un contorno poligonal se integra sumando sus lados.");
card(3,"3.1","¿Qué ocurre al reparametrizar un camino conservando orientación?","La integral no cambia bajo una reparametrización regular creciente.","Si se invierte la orientación cambia el signo.");
card(3,"3.1","¿Qué es una primitiva holomorfa de f?","Una función holomorfa F en el dominio con F′=f.","Para f(z)=z² puede tomarse F(z)=z³/3.");
card(3,"3.1","¿Qué dice el teorema fundamental para integrales complejas?","Si F′=f, la integral de f sobre γ es F(γ(b))−F(γ(a)).","Si γ es cerrado, el resultado es cero.");
card(3,"3.1","¿Qué fórmula da la variación de una función C¹ a lo largo de un camino?","La diferencia entre sus valores extremos es la integral de f_z dz+f_z̄ dz̄ sobre el camino.","Si f es holomorfa, desaparece el segundo término.");
card(3,"3.1","¿Cuánto vale la integral de (z−a)ⁿ sobre un círculo centrado en a, antihorario?","Para n entero vale cero salvo n=−1, cuando vale 2πi.","Es el cálculo básico que selecciona el residuo.");
card(3,"3.2","¿Qué pasa en la fórmula de Cauchy si a queda fuera del disco cerrado?","La integral de f(z)/(z−a) es cero si f es holomorfa en un entorno del disco cerrado.","El integrando es entonces holomorfo en todo el disco.");
card(3,"3.2","¿Qué cambia en Cauchy al recorrer el borde en sentido horario?","La integral cambia de signo.","La integral de f(z)/(z−a) pasa a ser −2πi f(a) para un punto interior.");
card(3,"3.2","¿Por qué Cauchy no se aplica con a sobre el contorno?","El denominador se anula sobre el camino y la integral ordinaria puede no estar definida.","Hace falta otro planteo para valores principales o indentaciones.");
card(3,"3.3","¿Qué es una función analítica en un abierto?","Una función que cerca de cada punto coincide con una serie de potencias convergente.","No exige una única serie centrada en un punto que represente todo el dominio.");
card(3,"3.3","¿Qué determina el radio de convergencia de una serie de potencias?","1/R es el límite superior de |aₙ|^(1/n), con las convenciones para R=0 o infinito.","Dentro del radio hay convergencia normal en compactos; fuera, divergencia.");
card(3,"3.3","¿Qué se puede afirmar sobre la frontera del disco de convergencia?","El radio por sí solo no decide la convergencia en la frontera.","La serie geométrica diverge en todo el círculo unidad, pero ∑ zⁿ/n² converge allí absolutamente.");
card(3,"3.3","¿Se puede derivar una serie de potencias término a término?","Sí, dentro de su disco de convergencia; la serie derivada tiene el mismo radio.","También se puede integrar término a término localmente.");
card(3,"3.3","¿Hasta dónde garantiza Taylor representar a una holomorfa?","En todo disco centrado en a que esté contenido en el dominio de holomorfía.","Una singularidad que impide prolongar la función limita el radio de Taylor.");
card(3,"3.3","¿Por qué una holomorfa tiene primitivas locales?","En un disco donde tiene serie de potencias, se integra cada término y se obtiene una primitiva.","La existencia local no garantiza una primitiva global.");
card(3,"3.3","¿Qué concluyen las estimaciones de Cauchy si una entera crece como |z|ᵐ?","Si m es entero no negativo y |f(z)|≤C(1+|z|ᵐ), f es un polinomio de grado a lo sumo m.","Las derivadas de orden mayor que m se anulan al dejar crecer el radio.");
card(3,"3.4","¿Qué convergencia permite pasar el límite dentro de una integral sobre un camino fijo?","La convergencia uniforme sobre la imagen del camino, que tiene longitud finita.","ML acota la diferencia de integrales por longitud multiplicada por el error uniforme.");
card(3,"3.4","¿Qué sucede con todas las derivadas en el teorema de convergencia holomorfa?","Si fₙ converge uniformemente en compactos a f, sus derivadas de cualquier orden fijo convergen localmente uniformemente a las de f.","Se aplica la fórmula integral de Cauchy en discos internos.");
card(3,"3.4","¿Cuándo una serie de holomorfas puede derivarse término a término?","Si converge uniformemente en compactos; en particular, si converge normalmente en compactos.","Las series de derivadas convergen uniformemente en compactos al derivar la suma.");
card(4,"4.1","¿Qué es una función meromorfa en Ω?","Una función holomorfa salvo polos aislados en Ω; también se puede describir localmente como cociente de holomorfas con denominador no idénticamente nulo.","Una singularidad esencial no está permitida en Ω.");
card(4,"4.1","¿Qué es una singularidad aislada?","Un punto a donde f no está definida o no es holomorfa, pero es holomorfa en algún disco perforado centrado en a.","La clasificación exige un entorno perforado libre de otras singularidades.");
card(4,"4.1","¿Cómo se reconoce un polo de orden m mediante factorización?","f(z)=(z−a)^(−m)g(z), con g holomorfa cerca de a y g(a)≠0.","El entero m debe ser positivo y es único.");
card(4,"4.1","¿Qué criterio de límite caracteriza un polo?","|f(z)| tiende a infinito cuando z tiende a a.","Equivale a que 1/f tenga un cero en a tras extenderla por 0.");
card(4,"4.1","¿Qué garantiza el teorema de singularidades removibles?","Si f es holomorfa y acotada en un entorno perforado de a, admite extensión holomorfa en a.","Para sin(z)/z, la extensión toma el valor 1 en 0.");
card(4,"4.1","¿Qué es la parte principal de Laurent?","La suma de los términos con potencias negativas de z−a.","Para un polo es una suma finita; para una removible es cero.");
card(4,"4.1","¿Qué forma tiene un desarrollo de Laurent en un anillo?","Una suma de potencias enteras de z−a, positivas y negativas, convergente en el anillo.","Los coeficientes son únicos para ese anillo.");
card(4,"4.1","¿Puede una misma función tener distintos desarrollos de Laurent según el anillo?","Sí. Los anillos separados por singularidades pueden dar desarrollos distintos.|Para 1/(z−1), usá −∑zⁿ si |z|<1 y ∑z^(−n−1) si |z",">1.");
card(4,"4.1","¿Cómo se obtiene un coeficiente de Laurent mediante una integral?","aₙ=(1/(2πi))∮ f(z)/(z−a)^(n+1) dz sobre un círculo antihorario del anillo.","Para n=−1 se obtiene el residuo.");
card(4,"4.1","¿El residuo depende de todos los términos negativos de Laurent?","Solo del coeficiente de (z−a)⁻¹.","1/z³ tiene residuo cero aunque tiene un polo.");
card(4,"4.1","¿Qué propiedad de linealidad cumple el residuo?","Res(αf+βg,a)=αRes(f,a)+βRes(g,a).","Los residuos se pueden calcular por separado y luego sumar.");
card(4,"4.1","¿Cómo se calcula el residuo de g/h si h tiene un cero simple en a?","Res(g/h,a)=g(a)/h′(a), con g,h holomorfas y h′(a)≠0.","Si g(a)=0, la singularidad se remueve y el residuo vale cero.");
card(4,"4.1","¿Qué residuo tiene la derivada de una función meromorfa?","Cero en cada singularidad aislada.","Al derivar Laurent, ningún término produce una potencia −1 con coeficiente no nulo.");
card(4,"4.1","¿Qué valores puede tomar el índice de un lazo?","Siempre valores enteros, si el punto está fuera de la imagen del lazo.","Puede ser negativo o mayor que uno.");
card(4,"4.1","¿Cómo varía el índice al mover el punto sin cruzar el lazo?","Permanece constante en cada componente conexa del complemento del lazo.","En la componente no acotada el índice es cero.");
card(4,"4.1","¿Qué pasa con el índice al invertir o repetir un lazo?","Invertir cambia su signo; recorrerlo n veces multiplica el índice por n.","Dos vueltas horarias alrededor de a dan índice −2.");
card(4,"4.1","¿Qué es una homotopía de lazos en Ω?","Una deformación continua H(s,t) dentro de Ω tal que para cada s el camino en t es cerrado.","La deformación debe evitar los puntos excluidos del dominio.");
card(4,"4.1","¿Por qué la homotopía de lazos es una relación de equivalencia?","Tiene reflexividad por la homotopía constante, simetría al invertir s y transitividad al concatenar deformaciones.","Esto permite hablar de clases de homotopía.");
card(4,"4.1","¿Qué significa que un dominio sea simplemente conexo?","Es conexo por caminos y todo lazo puede deformarse dentro de él hasta un lazo constante.","ℂ es simplemente conexo; ℂ sin el origen no.");
card(4,"4.1","¿Qué es un abierto estrellado?","Existe un punto a del abierto tal que el segmento de a a cualquier punto del abierto queda dentro de él.","Todo abierto convexo no vacío es estrellado.");
card(4,"4.1","¿Por qué un abierto estrellado es simplemente conexo?","Cada lazo se contrae al centro a mediante H(s,t)=(1−s)γ(t)+sa.","El carácter estrellado garantiza que la deformación quede en el abierto.");
card(4,"4.1","¿Qué dice la invariancia homotópica de las integrales holomorfas?","Lazos homotópicos en Ω tienen la misma integral de toda f holomorfa en Ω.","No se puede deformar un camino atravesando un polo del integrando.");
card(4,"4.1","¿Por qué el índice es invariante por homotopías que evitan a?","Se aplica la invariancia de integrales a la función holomorfa 1/(z−a) en el dominio sin a.","Un círculo de índice 1 no se contrae evitando su centro.");
card(4,"4.1","¿Qué dice el teorema de Cauchy en un dominio simplemente conexo?","La integral de toda función holomorfa sobre todo lazo del dominio es cero.","La simple conexidad permite contraer el lazo.");
card(4,"4.1","¿Qué singularidades contribuyen en el teorema de residuos?","Las de índice no nulo respecto del lazo, ponderadas por ese índice.","Un polo exterior a un círculo simple tiene contribución cero.");
card(4,"4.1","¿Qué se debe revisar antes de sumar residuos?","El dominio de holomorfía o meromorfía, la ausencia de polos sobre el camino, los índices y la orientación.","Sumar todos los polos sin atender al contorno puede dar un resultado incorrecto.");
card(4,"4.2","¿Qué estrategia permite calcular una integral real con un semicírculo?","Se integra una extensión meromorfa sobre el segmento real y el arco, se suman residuos y se prueba que la contribución del arco desaparece.","Finalmente se toma el límite del segmento hacia toda la recta.");
card(4,"4.2","¿Qué cota hace desaparecer un arco semicircular para una función O(1/R²)?","Su longitud es πR y el supremo del integrando es O(1/R²), así que ML da O(1/R).","La cota debe ser uniforme sobre todo el arco.");
card(4,"4.2","¿Qué relación entre grados ayuda para integrales racionales sobre la recta?","Si el grado del denominador supera al del numerador al menos en dos, el arco grande desaparece por ML.","También hay que excluir polos reales para una integral ordinaria de este tipo.");
card(4,"4.2","¿Cómo se transforma una integral trigonométrica con z=eⁱᵗ?","cos t=(z+1/z)/2, sin t=(z−1/z)/(2i) y dt=dz/(iz).","El intervalo de 0 a 2π recorre el círculo unidad una vez en sentido antihorario.");
card(4,"4.2","¿Qué precaución exigen los polos sobre el eje real?","La integral impropia ordinaria puede divergir; no se aplica directamente el contorno que atraviesa esos polos.","Un valor principal es una noción diferente y requiere justificar su existencia.");
card(4,"4.2","¿Cómo se usa la paridad en integrales reales por residuos?","Si el integrando es par e integrable, la integral sobre la recta es dos veces la integral sobre el semieje positivo.","Para 1/(1+x²), la integral de 0 a infinito es π/2.");
card(4,"4.3","¿Qué dice el teorema fundamental del álgebra?","Todo polinomio complejo no constante tiene al menos una raíz compleja.","Por factorización sucesiva, uno de grado n tiene n raíces contando multiplicidades.");
card(4,"4.3","¿Cómo se demuestra el teorema fundamental del álgebra con Liouville?","Si un polinomio no constante P no tuviera ceros, 1/P sería entera y acotada, luego constante: contradicción.|Fuera de un disco, |P"," tiende a infinito; dentro se usa compacidad.");
card(4,"4.3","¿Qué es el orden o multiplicidad de un cero a?","El menor m≥1 con f⁽ᵐ⁾(a)≠0; entonces f(z)=(z−a)ᵐg(z), g(a)≠0.","Se supone que f no es idénticamente nula cerca de a.");
card(4,"4.3","¿Qué dice el principio de los ceros aislados?","Una holomorfa no idénticamente nula en un dominio tiene ceros aislados.","Si todos los coeficientes de Taylor en un punto son cero, es nula en el dominio.");
card(4,"4.3","¿Puede una holomorfa no nula tener infinitos ceros en un compacto interno?","No: tendrían un punto de acumulación en el dominio.","Sí puede tener infinitos ceros que se escapen a la frontera o al infinito.");
card(4,"4.3","¿Qué es una prolongación analítica?","Una función holomorfa en un dominio mayor que coincide con la original en el dominio inicial.","La suma geométrica del disco unidad se prolonga mediante 1/(1−z) a ℂ sin 1.");
card(4,"4.3","¿Qué garantiza la unicidad de la prolongación analítica?","El principio de identidad en un dominio conexo.","Coincidir en un abierto no vacío basta para coincidir en todo el dominio común conexo.");
card(4,"4.3","¿Qué afirma la densidad de polinomios en los espacios ponderados del apunte?","Los polinomios son densos en L²(ℝ,e^(−x²)dx) y en L²((0,∞),e^(−x)dx).","La aproximación es en norma L² con el peso correspondiente, no necesariamente uniforme.");
card(4,"4.3","¿Cómo se relaciona la ortogonalidad a todos los polinomios con esa densidad?","En esos espacios, si una función es ortogonal a todos los polinomios, es cero como elemento de L².","La prueba del apunte usa una transformada holomorfa y el principio de identidad.");
card(4,"4.3","¿Qué es la derivada logarítmica de f?","El cociente f′/f, definido donde f no se anula ni tiene polos.","Si existe un logaritmo holomorfo L de f, entonces L′=f′/f.");
card(4,"4.3","¿Cuál es el residuo de f′/f en un cero de orden m?","Es m.","Usá f=(z−a)ᵐg para escribir f′/f=m/(z−a)+g′/g.");
card(4,"4.3","¿Cuál es el residuo de f′/f en un polo de orden m?","Es −m.","Los polos se cuentan con signo negativo en el principio del argumento.");
card(4,"4.3","¿Qué dice el principio del argumento para un contorno simple positivo?","(1/(2πi))∮ f′/f dz=N−P, contando ceros y polos interiores con multiplicidad.","f debe ser meromorfa en un entorno del interior y del borde, sin ceros ni polos sobre el borde.");
card(4,"4.3","¿Cómo interpreta el principio del argumento la imagen del borde?","El índice de f∘γ respecto de 0 cuenta ceros menos polos para un borde simple positivo.","El recorrido de f(γ) mide el cambio total de argumento de f.");
card(4,"4.3","¿Qué hipótesis de Rouché se verifica solo sobre el borde?","La desigualdad estricta |g|<|f| para comparar f y f+g.","Ambas funciones deben ser holomorfas también en el interior.");
card(4,"4.3","¿Cómo se elige el término dominante para aplicar Rouché?","Se busca una parte cuyo módulo en el borde supere la cota del resto y cuyos ceros se conozcan.|En |z","=1, 3z domina z⁵+1 porque 3>2.");
card(4,"4.3","¿Cuántos ceros de z⁴+5z+1 quedan en el disco unidad?","Uno, contando multiplicidades.|En el borde, |z⁴+1|≤2<5=|5z","; se compara con 5z.");
card(4,"4.3","¿Cuántos ceros de z⁴+z+1 quedan en |z|<2?","Cuatro, contando multiplicidades.|En |z|=2, |z+1|≤3<16=|z⁴",".");
card(4,"4.4","¿La media de |f| coincide siempre con |f(a)|?","No. La media compleja de f sí es f(a); la desigualdad triangular da |f(a)|≤media de |f|.|Para f(z)=z en un círculo centrado en 0, |f(0)|=0 y la media de |f"," es el radio.");
card(4,"4.4","¿Qué fórmula de media sobre el disco se deduce de la media sobre circunferencias?","f(a) es la integral de f sobre el disco dividida por su área πr².","Se integran las medias circulares en radios de 0 a r usando coordenadas polares.");
card(4,"4.4","¿Qué principio del mínimo vale para una holomorfa sin ceros?","Si |f| tiene un mínimo local interior y f no se anula, f es constante en el dominio conexo.","Se aplica módulo máximo a 1/f.");
card(4,"4.4","¿Por qué hay que excluir los ceros en el principio del mínimo del módulo?","Porque una función no constante puede alcanzar módulo mínimo cero en un punto interior.","f(z)=z alcanza su mínimo de módulo en 0.");
card(4,"4.4","¿Qué se concluye si una holomorfa tiene módulo constante en un dominio?","Es constante.","Cada punto es un máximo local del módulo.");
card(4,"4.4","¿Qué se concluye si una holomorfa toma solo valores reales en un dominio?","Es constante.","Cauchy–Riemann con parte imaginaria cero fuerza ambas parciales de la parte real a ser cero.");
card(4,"4.4","¿Dónde se alcanza el máximo del módulo en un dominio acotado?","Si f es holomorfa dentro y continua en la clausura, el máximo sobre la clausura se alcanza en la frontera.","La clausura es compacta y el principio del máximo controla el interior.");
card(4,"4.5","¿Cómo se construye una primitiva mediante integrales?","Se fija a y se define F(z) como la integral de f sobre cualquier camino de a a z, si es independiente del camino.","La anulación de integrales sobre lazos garantiza esa independencia.");
card(4,"4.5","¿Cómo difieren dos primitivas de una misma función en un dominio?","En una constante compleja.","La derivada de la diferencia es cero y el dominio es conexo.");
card(4,"4.5","¿Por qué una holomorfa no nula en un dominio simplemente conexo tiene logaritmo holomorfo?","f′/f es holomorfa y tiene primitiva L; ajustando una constante se consigue exp(L)=f.","La función f debe evitar 0 en todo el dominio.");
card(4,"4.5","¿Es suficiente tomar cualquier primitiva de f′/f para que su exponencial sea f?","No: su exponencial es un múltiplo constante no nulo de f; hay que normalizar en un punto.","Se elige L(a) como un logaritmo del número f(a).");
card(4,"4.5","¿Cómo se obtiene una raíz holomorfa de una función sin ceros?","En un dominio simplemente conexo se elige L con exp(L)=f y se define exp(L/n).","Su potencia n-ésima es f.");
card(4,"4.5","¿Qué afirma el teorema de productos infinitos del apunte?","Si ∑fₙ converge normalmente en cada disco cerrado interno y los fₙ son holomorfos, los productos parciales de (1+fₙ) convergen localmente uniformemente a una función holomorfa.","La hipótesis controla la suma de los tamaños de las perturbaciones de 1.");
card(4,"4.5","¿Qué papel juega el logaritmo al estudiar productos infinitos?","Para términos suficientemente pequeños, convierte el producto de (1+fₙ) en la exponencial de la suma de log(1+fₙ).|La cota de log(1+w) por C|w"," cerca de 0 controla la serie.");
card(4,"4.5","¿Puede anularse el límite de un producto normalmente convergente de (1+fₙ)?","En un punto, se anula exactamente si algún factor se anula allí; la cola de factores pequeños tiene producto no nulo.","La afirmación usa la convergencia absoluta de las perturbaciones en ese punto.");
card(4,"4.5","¿Cómo se define Γ(z) inicialmente?","Γ(z) es la integral de 0 a infinito de e^(−t)t^(z−1)dt, para Re z>0, usando el logaritmo real de t>0.","La restricción en la parte real asegura integrabilidad cerca de 0.");
card(4,"4.5","¿Qué ecuación funcional satisface Gamma?","Γ(z+1)=zΓ(z); inicialmente se obtiene integrando por partes en Re z>0.","La identidad continúa donde ambos miembros están definidos meromórficamente.");
card(4,"4.5","¿Cómo interpola Gamma a los factoriales?","Γ(n+1)=n! para n entero no negativo.","Γ(1)=1, Γ(2)=1 y Γ(3)=2.");
card(4,"4.5","¿Dónde tiene polos la prolongación meromorfa de Gamma?","En 0, −1, −2, …; son polos simples.","La recurrencia permite prolongar sucesivamente a la izquierda.");
card(4,"4.5","¿Qué es la constante de Euler usada en el producto de Gamma?","γ es el límite de la suma de 1/k desde k=1 hasta n menos ln n.","No es el número e ni un camino de integración en esta fórmula.");
card(4,"4.5","¿Qué producto representa el recíproco de Gamma?","1/Γ(z)=z exp(γz) ∏ desde k=1 hasta infinito de (1+z/k)exp(−z/k).","El recíproco es entero y tiene ceros en los enteros no positivos.");
card(4,"4.5","¿Por qué convergen normalmente las perturbaciones del producto de Gamma?","En cada disco |z|≤R, (1+z/k)exp(−z/k)−1 está acotado por C_R/k² para k grande.","La serie de 1/k² converge.");
card(4,"4.6","¿Cómo se expresa el laplaciano con Wirtinger?","Δ=4∂z∂z̄=4∂z̄∂z para funciones C².","La conmutación de derivadas mixtas usa regularidad C².");
card(4,"4.6","¿Puede una función armónica tomar valores complejos?","Sí: es C² y su laplaciano es cero, equivalentemente sus partes real e imaginaria son armónicas reales.","El apunte usa esta definición antes de especializar a funciones reales.");
card(4,"4.6","¿Cómo se representa una armónica compleja en un abierto simplemente conexo?","Como f+ḡ, donde f y g son holomorfas.","Sin simple conexidad la representación sigue siendo válida localmente en discos.");
card(4,"4.6","¿Una función armónica es necesariamente holomorfa?","No. La condición del laplaciano es más débil.","Re z es armónica, pero no es derivable complejamente en ningún punto.");
card(4,"4.6","¿Qué ecuaciones permiten hallar una conjugada armónica v de u?","vᵧ=uₓ y vₓ=−uᵧ.","Se integra una ecuación y se ajusta la función de la otra variable con la segunda.");
card(4,"4.6","¿Por qué la conjugada armónica solo es única salvo constante real?","Si u+iv₁ y u+iv₂ son holomorfas en un dominio, su diferencia tiene parte real cero y es constante imaginaria.","Por tanto v₁−v₂ es una constante real.");
card(4,"4.6","¿Por qué ln|z| no tiene conjugada armónica global en ℂ sin 0?","Una conjugada produciría un argumento continuo global y un logaritmo global, que no existen.","Sí admite conjugadas en discos que evitan 0.");
card(4,"4.6","¿Qué propiedad de media satisface una armónica real?","Su valor en el centro de un disco cerrado interno es el promedio de sus valores sobre la circunferencia.","Se deduce localmente representándola como parte real de una holomorfa.");
card(4,"4.6","¿Qué principio del máximo satisface una armónica real?","Si alcanza un máximo local interior, es constante en la componente conexa del punto.","También vale para mínimos aplicando el resultado a −u.");
card(4,"4.6","¿Por qué la condición de borde determina de manera única una armónica?","En un dominio acotado, dos armónicas continuas en la clausura con los mismos valores de borde tienen diferencia cero por máximo y mínimo.","Es la unicidad del problema de Dirichlet bajo esas hipótesis.");
card(4,"4.6","¿Cómo se comprueba que x²−y² es armónica?","Sus segundas derivadas son 2 y −2; su suma es cero.","En cambio x²+y² tiene laplaciano 4.");
card(4,"4.6","¿Toda armónica real tiene conjugada al menos localmente?","Sí, restringiendo a discos contenidos en el dominio.","La obstrucción a una conjugada global es topológica.");

const questions=[];
function q(ch,section,type,prompt,options,correct,explanation){questions.push({id:'q'+questions.length,ch,section,type,prompt,options,correct,explanation});}
function vf(ch,s,p,c,e){q(ch,s,'vf',p,['Verdadero','Falso'],c?0:1,e);}
vf(1,'1.3','Todo conjunto cerrado de ℂ es compacto.',false,'También debe ser acotado. ℂ es cerrado y no es compacto.');
vf(1,'1.4','La convergencia normal de una serie implica su convergencia uniforme.',true,'La cola uniforme queda acotada por la cola de ∑ sup |fₙ|, que tiende a cero.');
vf(2,'2.1','La función f(z)=z̄ es holomorfa.',false,'El cociente incremental es h̄/h: vale 1 para h real y −1 para h imaginario.');
vf(2,'2.2','Si u,v son C¹ y cumplen Cauchy–Riemann en un abierto, u+iv es holomorfa allí.',true,'La regularidad C¹ permite pasar de la derivada real al diferencial complejo.');
vf(2,'2.3','La función z² es conforme en 0.',false,'Su derivada en 0 es cero. Las direcciones se duplican en ese punto.');
vf(2,'2.4','Existe una rama continua del logaritmo en todo ℂ ∖ {0}.',false,'Una vuelta al origen cambia el argumento continuo en 2π.');
vf(3,'3.1','Una función con primitiva tiene integral nula sobre todo camino cerrado de su dominio.',true,'La integral es F(γ(b))−F(γ(a)), que vale cero si el camino cierra.');
vf(3,'3.2','Ser holomorfa cerca de una circunferencia basta para concluir que su integral es cero.',false,'1/z es holomorfa cerca de |z|=1, pero su integral antihoraria es 2πi. Falta controlar el interior.');
vf(3,'3.4','Un límite puntual de funciones holomorfas siempre es holomorfo.',false,'El teorema del apunte requiere convergencia uniforme en compactos; la puntual no basta.');
vf(4,'4.1','Un polo de orden dos siempre tiene residuo cero.',false,'1/z²+1/z tiene polo doble y residuo 1. El orden no determina el coeficiente de z⁻¹.');
vf(4,'4.3','Una función entera acotada es constante.',true,'Es el teorema de Liouville; las estimaciones de Cauchy fuerzan f′=0.');
vf(4,'4.3','Si los ceros de una holomorfa acumulan en un punto interior de su dominio conexo, es idénticamente nula.',true,'Es el principio de ceros aislados: una función no idénticamente nula solo tiene ceros aislados.');
vf(4,'4.4','Una holomorfa no constante puede alcanzar un máximo local de su módulo en el interior.',false,'Lo impide el principio del módulo máximo.');
vf(4,'4.6','Toda función armónica real en un dominio tiene una conjugada armónica global.',false,'Sin simple conexidad puede fallar: ln|z| es armónica en ℂ ∖ {0}, pero su conjugada sería un argumento global.');
q(1,'1.1','calc','¿Cuánto vale (1+i)/(1−i)?',['1','i','−i','−1'],1,'Multiplicá por (1+i)/(1+i): (1+i)²/2 = 2i/2 = i.');
q(1,'1.2','calc','¿Cuáles son las raíces de z³=8?',['2, −2, 0','2, −1+i√3, −1−i√3','8, 8i, −8','2, 2i, −2'],1,'Tienen módulo 2 y argumentos 0, 2π/3 y 4π/3.');
q(1,'1.3','theory','¿Cuál de estos conjuntos es compacto?',['|z| < 1','ℂ ∖ {0}','1 ≤ |z| ≤ 2','Im z > 0'],2,'El anillo cerrado es cerrado y acotado; los otros conjuntos no reúnen ambas condiciones.');
q(2,'2.2','calc','Si f(z)=z², ¿cuánto vale f′(1+i)?',['2','2+2i','1+2i','2i'],1,'f′(z)=2z; por lo tanto f′(1+i)=2+2i.');
q(2,'2.1','calc','¿En qué puntos es derivable complejamente f(z)=|z|²?',['En ninguno','Solo en 0','En todo ℂ','Solo en el eje real'],1,'u=x²+y² y v=0. Cauchy–Riemann exige x=y=0. En 0, |h|²/h=h̄→0. No es holomorfa en ningún abierto.');
q(2,'2.4','calc','¿Cuál es Log(−i) en la rama principal?',['3πi/2','−πi/2','πi/2','−1'],1,'El módulo es 1 y el argumento principal es −π/2.');
q(2,'2.3','theory','Si f es holomorfa y f′(a) ≠ 0, ¿qué se garantiza?',['Inyectividad global','Inversa holomorfa local','Que f es entera','Que f preserva longitudes'],1,'El teorema de inversión local da una inversa holomorfa en entornos adecuados. No asegura inyectividad global.');
q(3,'3.2','calc','Para γ: |z|=2 antihorario, ¿cuánto vale ∮γ eᶻ/z dz?',['0','2π','2πi','e²'],2,'Aplicá Cauchy a f(z)=eᶻ y a=0: 2πi e⁰ = 2πi.');
q(3,'3.3','calc','Para γ: |z|=1 antihorario, ¿cuánto vale ∮γ eᶻ/z³ dz?',['0','πi','2πi','4πi'],1,'La fórmula para n=2 da 2πi f″(0)/2! = πi.');
q(3,'3.3','theory','Si |f|≤M en |z|=R y f es holomorfa en un entorno del disco cerrado, ¿qué cota vale?',['|f′(0)| ≤ MR','|f′(0)| ≤ M/R','|f′(0)| = M/R','|f′(0)| ≤ M²'],1,'Es la estimación de Cauchy con n=1. Es una cota, no necesariamente una igualdad.');
q(3,'3.4','calc','Para 0<r<1, ¿cuánto vale sup sobre |z|≤r de |zⁿ|?',['1','n r','rⁿ','0'],2,'|z|ⁿ aumenta con |z|, por eso su máximo en el disco cerrado es rⁿ→0.');
q(4,'4.1','calc','¿Cuál es Res(eᶻ/z²,0)?',['0','1','2','1/2'],1,'eᶻ/z² = z⁻² + z⁻¹ + 1/2 + … El coeficiente de z⁻¹ es 1.');
q(4,'4.1','calc','¿Cuál es Res(1/(z²+1),i)?',['1/(2i)','1','−1','2i'],0,'Es un polo simple: lim(z→i) 1/(z+i) = 1/(2i).');
q(4,'4.1','calc','Para |z|=2 antihorario, ¿cuánto vale ∮ dz/(z²+1)?',['2πi','π','0','−π'],2,'Se incluyen ambos polos ±i. Los residuos 1/(2i) y −1/(2i) se cancelan.');
q(4,'4.3','calc','¿Cuántos ceros tiene z⁵+3z+1 en |z|<1, contando multiplicidades?',['0','1','3','5'],1,'En |z|=1, |z⁵+1|≤2<3=|3z|. Por Rouché hay tantos ceros como 3z: uno.');
q(4,'4.3','theory','Para usar el principio de identidad, el punto de acumulación debe estar…',['En cualquier lugar de ℂ','En la frontera','Dentro del dominio conexo','En el infinito'],2,'La acumulación en la frontera no permite aplicar el teorema.');
q(4,'4.6','calc','Una conjugada armónica de u=x²−y² es…',['x²+y²','−2xy','2xy','x+y'],2,'Cauchy–Riemann pide vᵧ=2x y vₓ=2y. Así v=2xy+C.');
const exercises=[];
function ex(ch,section,title,level,prompt,hint,solution){exercises.push({id:'e'+exercises.length,ch,section,title,level,prompt,hint,solution});}
ex(1,'1.1','Dividir sin calculadora','Inicial','Calculá (3+4i)/(1−2i) y su módulo.','Multiplicá numerador y denominador por 1+2i.','El numerador es −5+10i y el denominador 5. Resultado: −1+2i. Su módulo es √5, también igual a |3+4i|/|1−2i|=5/√5.');
ex(1,'1.2','Raíces y geometría','Inicial','Encontrá las cuatro raíces de −16 y ubicá sus argumentos.','Escribí −16 = 16 exp(iπ).','Las raíces tienen módulo 2 y argumentos π/4+kπ/2, k=0,1,2,3. Son √2(1+i), √2(−1+i), √2(−1−i), √2(1−i).');
ex(1,'1.3','Abierto, cerrado, compacto','Intermedio','Clasificá A={z: 1<|z|≤2}. Hallá interior, clausura y frontera.','Separá las condiciones en las dos circunferencias.','A no es abierto ni cerrado y no es compacto. Interior: 1<|z|<2. Clausura: 1≤|z|≤2. Frontera: |z|=1 o |z|=2.');
ex(1,'1.4','Puntual versus uniforme','Intermedio','Estudiá fₙ(z)=zⁿ en D={|z|<1} y en cada disco |z|≤r<1.','Calculá el supremo de |z|ⁿ en ambos conjuntos.','En D el límite puntual es 0, pero sup_D |zⁿ|=1: no hay convergencia uniforme. En |z|≤r, el supremo es rⁿ→0: sí hay convergencia uniforme.');
ex(2,'2.2','Reconocer una holomorfa','Inicial','Para f(x+iy)=x²−y²+i2xy, verificá Cauchy–Riemann y calculá f′.','Derivá u y v respecto de x e y.','uₓ=2x=vᵧ y uᵧ=−2y=−vₓ. Son polinomios, luego son C¹ y f es entera. f′=uₓ+ivₓ=2x+2iy=2z.');
ex(2,'2.1','Derivable en un punto','Intermedio','Demostrá que |z|² tiene derivada compleja en 0 pero no es holomorfa en ningún abierto no vacío.','Usá directamente el cociente incremental en 0 y CR fuera de 0.','En 0: |h|²/h=h̄→0. Fuera de 0, CR para u=x²+y²,v=0 exige 2x=2y=0, imposible. Solo es derivable en 0, que no es un abierto.');
ex(2,'2.4','Un logaritmo que cambia de rama','Intermedio','Calculá Log(i)+Log(i) y comparalo con Log(i·i). ¿Qué problema aparece?','En el apunte la rama principal excluye el semieje real no positivo.','Log(i)+Log(i)=iπ. El producto es −1, que está fuera del dominio de la rama principal holomorfa. No se puede escribir Log(−1) en esa rama. Esto muestra por qué hay que verificar dominios antes de usar reglas del logaritmo.');
ex(2,'2.3','Escala y giro','Inicial','Para f(z)=z² cerca de a=1+i, hallá el factor de escala y el ángulo de giro local.','El diferencial multiplica por f′(a).','f′(a)=2+2i. Escala: |2+2i|=2√2. Giro: arg(2+2i)=π/4 módulo 2π. Como la derivada no es cero, preserva ángulos orientados localmente.');
ex(3,'3.1','Una integral parametrizada','Inicial','Calculá ∮γ z̄ dz sobre γ(t)=eⁱᵗ, 0≤t≤2π.','En la circunferencia, z̄=e⁻ⁱᵗ.','γ′(t)=ieⁱᵗ, entonces z̄ dz=i dt y la integral vale 2πi. No se puede aplicar el teorema de Cauchy a z̄.');
ex(3,'3.3','Cauchy para derivadas','Intermedio','Calculá ∮ eᶻ/(z−1)³ dz sobre |z|=2 antihorario.','Usá la fórmula de Cauchy con n=2 y a=1.','f(z)=eᶻ es entera y a=1 está dentro. La integral es 2πi f″(1)/2! = πie.');
ex(3,'3.3','Demostrar Liouville','Demostración','Probá que una función entera acotada es constante usando las estimaciones de Cauchy.','Fijá un punto a y dejá crecer el radio R.','Si |f|≤M en ℂ, para cualquier R>0 se tiene |f′(a)|≤M/R. Al tomar R→∞ resulta f′(a)=0. Como a es arbitrario y ℂ es conexo, f es constante.');
ex(3,'3.4','Sumar y derivar','Intermedio','Justificá que ∑ desde n=0 de zⁿ = 1/(1−z) y derivá término a término en |z|<1.','Usá convergencia normal en |z|≤r<1.','∑ sup |zⁿ|=∑rⁿ<∞. La suma geométrica es 1/(1−z). El teorema de series holomorfas permite derivar localmente: ∑ desde n=1 de n zⁿ⁻¹ = 1/(1−z)².');
ex(4,'4.1','Tres singularidades','Inicial','Clasificá en 0: sin(z)/z, 1/z³ y exp(1/z). Calculá sus residuos.','Escribí las series de Laurent.','sin(z)/z=1−z²/6+…: removible, residuo 0. 1/z³: polo de orden 3, residuo 0. exp(1/z)=1+1/z+1/(2z²)+…: esencial, residuo 1.');
ex(4,'4.1','Un polo doble','Intermedio','Calculá ∮ eᶻ/z² dz sobre |z|=1, primero antihorario y después horario.','El residuo en 0 es la derivada de eᶻ en 0.','Res(eᶻ/z²,0)=1. La integral antihoraria es 2πi; la horaria es −2πi.');
ex(4,'4.2','Una integral real','Intermedio','Calculá ∫ de −∞ a ∞ de dx/(1+x²) mediante un semicírculo superior.','Solo el polo i queda en el semiplano superior. Justificá que el arco desaparece.','Res(1/(1+z²),i)=1/(2i), luego la integral cerrada vale π. En el arco de radio R>1, ML da una cota πR/(R²−1)→0. Por tanto la integral real vale π.');
ex(4,'4.3','Contar sin resolver','Intermedio','Contá los ceros de z⁵+3z+1 dentro del disco unidad.','Compará 3z con z⁵+1 en el borde.','En |z|=1: |z⁵+1|≤2<3=|3z|. Rouché implica que el polinomio tiene un único cero, contando multiplicidades, dentro del disco.');
ex(4,'4.3','Acumulación en la frontera','Demostración','¿Por qué los ceros 1/n de una holomorfa en ℂ fuerzan que sea nula, pero los ceros 1−1/n en el disco unidad no permiten esa conclusión?','Ubicá el punto de acumulación en cada dominio.','En el primer caso 1/n→0∈ℂ, así que se aplica el principio de identidad. En el segundo el límite es 1, que no pertenece al disco abierto. La hipótesis del teorema falla; esa información sola no permite concluir que la función sea nula.');
ex(4,'4.4','Máximo y media','Intermedio','Para f(z)=z²+1 en |z|≤1, hallá el máximo de |f| y el promedio de f sobre |z|=1.','La desigualdad triangular da una cota alcanzable. La media recupera f(0).','|z²+1|≤|z|²+1≤2, con igualdad en z=±1. El máximo es 2. El promedio complejo sobre el círculo es f(0)=1, pues el promedio de e²ⁱᵗ es cero.');
ex(4,'4.5','Obstrucción a una primitiva','Demostración','Demostrá que 1/z no tiene primitiva global en ℂ ∖ {0}, pero sí en el semiplano Re z>0.','Integrá sobre el círculo unidad y luego examiná la simple conexidad del semiplano.','Sobre el círculo unidad antihorario la integral es 2πi, incompatible con una primitiva global. El semiplano derecho es simplemente conexo y evita 0, por lo que 1/z tiene primitiva allí: una rama del logaritmo.');
ex(4,'4.6','Construir una conjugada','Intermedio','Para u(x,y)=eˣ cos y, hallá una conjugada armónica y una función holomorfa con parte real u.','Usá vᵧ=uₓ y vₓ=−uᵧ.','vᵧ=eˣ cos y da v=eˣ sin y+C(x). La segunda ecuación da C′(x)=0. Así v=eˣ sin y+C y f(z)=eᶻ+iC.');
